import json,os,time,boto3
from botocore.config import Config
sqs=boto3.client("sqs",config=Config(connect_timeout=2,read_timeout=3,retries={"max_attempts":0}))
def handler(event,context):
    message="native-error:"+event["source_id"]+":"+("雪🙂Z"*event.get("error_repeat",1))
    receipt={"kind":"runtime-audit","event":event,"aws_request_id":context.aws_request_id,"invoked_function_arn":context.invoked_function_arn,"function_version":context.function_version,"time_unix":time.time(),"intended_error":message if event.get("fail") else None}
    if event.get("probe_queue"):
        try:
            out=sqs.send_message(QueueUrl=event["probe_queue"],MessageBody=json.dumps({"kind":"authority-positive-probe","source_id":event["source_id"]}))
            receipt["authority_probe"]={"code":"Success","message_id":out["MessageId"],"request_id":out["ResponseMetadata"]["RequestId"]}
        except Exception as e:
            receipt["authority_probe"]={"class":type(e).__name__,"error":getattr(e,"response",{}).get("Error",{}),"message":str(e)}
    sqs.send_message(QueueUrl=os.environ["AUDIT_QUEUE"],MessageBody=json.dumps(receipt,ensure_ascii=False))
    if event.get("fail"):raise RuntimeError(message)
    return {"source_id":event["source_id"],"runtime_request_id":context.aws_request_id,"answer":42,"unicode":"雪🙂"}

